func networkDelayTime(_ times: [[Int]], _ n: Int, _ k: Int) -> Int {
    var adj = [[(to: Int, w: Int)]](repeating: [], count: n + 1)
    for t in times { adj[t[0]].append((t[1], t[2])) }
    var dist = [Int](repeating: .max, count: n + 1)
    var heap = Heap<(d: Int, node: Int)>({ $0.d < $1.d })   // Heap from Kth Largest
    dist[k] = 0; heap.push((0, k))
    while let (d, u) = heap.pop() {
        if d > dist[u] { continue }
        for (v, w) in adj[u] where d + w < dist[v] {
            dist[v] = d + w; heap.push((dist[v], v))
        }
    }
    let worst = dist[1...].max()!
    return worst == .max ? -1 : worst
}
